623	+++ b/driver/vsim_filter.cpp
624	@@ -0,0 +1,73 @@
625	+// See vsim_filter.hpp.
626	+#include "vsim_filter.hpp"
627	+
628	+namespace andes_sim {
629	+namespace {
630	+
631	+bool is_blank(std::string_view s) {
632	+  for (char c : s)
633	+    if (c != ' ' && c != '\t' && c != '\r') return false;
634	+  return true;
635	+}
636	+
637	+// vsim's two-line startup banner, emitted on stdout before the program runs.
638	+bool is_banner_line(std::string_view s) {
639	+  return s.starts_with("Copyright (C)") || s.starts_with("Version :");
640	+}
641	+
642	+}  // namespace
643	+
644	+std::optional<uint64_t> parse_cycles_line(std::string_view line) {
645	+  constexpr std::string_view kMark = "cycles simulated";
646	+  const std::size_t pos = line.find(kMark);
647	+  if (pos == std::string_view::npos) return std::nullopt;
648	+  // Scan left over the space(s) before "cycles", then over the digit run -- so
649	+  // "<digits> cycles simulated" matches but "...Hz" / "loading..." do not.
650	+  std::size_t end = pos;
651	+  while (end > 0 && line[end - 1] == ' ') --end;
652	+  std::size_t begin = end;
653	+  while (begin > 0 && line[begin - 1] >= '0' && line[begin - 1] <= '9') --begin;
654	+  if (begin == end) return std::nullopt;  // no digit run before "cycles"
655	+  uint64_t v = 0;
656	+  for (std::size_t i = begin; i < end; ++i) v = v * 10 + (line[i] - '0');
657	+  return v;
658	+}
659	+
660	+std::string strip_vsim_banner(std::string_view buf) {
661	+  VsimFilter filter;
662	+  std::string out;
663	+  out.reserve(buf.size());
664	+  for (std::size_t pos = 0; pos < buf.size();) {
665	+    const std::size_t nl = buf.find('\n', pos);
666	+    const bool has_nl = nl != std::string_view::npos;
667	+    const std::string_view line =
668	+        buf.substr(pos, (has_nl ? nl : buf.size()) - pos);
669	+    if (filter.classify(1, line) == VsimFilter::Dest::kStdout) {
670	+      out.append(line);
671	+      if (has_nl) out.push_back('\n');
672	+    }
673	+    if (!has_nl) break;
674	+    pos = nl + 1;
675	+  }
676	+  return out;
677	+}
678	+
679	+VsimFilter::Dest VsimFilter::classify(int stream, std::string_view line) {
680	+  if (stream == 2) {  // stderr: vsim's [info] log (cycle count lives here)
681	+    if (const std::optional<uint64_t> n = parse_cycles_line(line)) {
682	+      cycles_ = n;          // lift the count; the driver re-prints it
683	+      return Dest::kDrop;
684	+    }
685	+    if (line.starts_with("[info]")) return Dest::kDrop;
686	+    return Dest::kStderr;   // [warn]/[error]/... -- real diagnostics survive
687	+  }
688	+  // stdout: the program's own output, prefixed by vsim's banner. Suppress the
689	+  // banner (and its trailing blank) only until the first real output line; after
690	+  // that, relay verbatim so program output is never second-guessed.
691	+  if (seen_program_output_) return Dest::kStdout;
692	+  if (is_banner_line(line) || is_blank(line)) return Dest::kDrop;
693	+  seen_program_output_ = true;
694	+  return Dest::kStdout;
695	+}
696	+
697	+}  // namespace andes_sim
