705	+// Unit tests for VsimFilter (the cycle-mode presentation filter): banner and
706	+// [info] suppression, cycle-count lifting, and program-output pass-through.
707	+// Pure -- no spawn. Plain assert-and-count harness.
708	+#include "vsim_filter.hpp"
709	+
710	+#include <string_view>
711	+
712	+#include "test_check.hpp"
713	+
714	+using andes_sim::parse_cycles_line;
715	+using andes_sim::strip_vsim_banner;
716	+using andes_sim::VsimFilter;
717	+using Dest = andes_sim::VsimFilter::Dest;
718	+
719	+int main() {
720	+  // --- parse_cycles_line: lift the count, ignore every other [info] line ---
721	+  CHECK(parse_cycles_line("[info] 3573 cycles simulated") == 3573u);
722	+  CHECK(parse_cycles_line("[info] 0 cycles simulated") == 0u);
723	+  // the neighbouring timing line has digits but is NOT a cycle count
724	+  CHECK(!parse_cycles_line("[info] 0.354s elapsed, 10093.220Hz").has_value());
725	+  CHECK(!parse_cycles_line("[info] loading segment: addr=0x100000").has_value());
726	+  CHECK(!parse_cycles_line("hello").has_value());
727	+
728	+  // --- stderr: drop [info], lift the cycle count, keep real diagnostics ---
729	+  {
730	+    VsimFilter f;
731	+    CHECK(f.classify(2, "[info] loading segment: addr=0x100000") == Dest::kDrop);
732	+    CHECK(f.classify(2, "[info] hart 0 reset vector: 0x100000") == Dest::kDrop);
733	+    CHECK(!f.cycles().has_value());  // none seen yet
734	+    CHECK(f.classify(2, "[info] 3573 cycles simulated") == Dest::kDrop);
735	+    CHECK(f.cycles() == 3573u);  // ...lifted, not relayed
736	+    CHECK(f.classify(2, "[info] 0.354s elapsed, 10093.220Hz") == Dest::kDrop);
737	+    // real diagnostics (above info level) survive to stderr
738	+    CHECK(f.classify(2, "[warn] something odd") == Dest::kStderr);
739	+    CHECK(f.classify(2, "[error] boom") == Dest::kStderr);
740	+  }
741	+
742	+  // --- stdout: drop the banner (+ its trailing blank), keep program output ---
743	+  {
744	+    VsimFilter f;
745	+    CHECK(f.classify(1, "Copyright (C) 2013-2026 Andes Technology Corporation. "
746	+                        "All rights reserved.") == Dest::kDrop);
747	+    CHECK(f.classify(1, "Version : fcf5ecb") == Dest::kDrop);
748	+    CHECK(f.classify(1, "") == Dest::kDrop);          // banner's trailing blank
749	+    CHECK(f.classify(1, "hello") == Dest::kStdout);   // first real output
750	+    // Past the banner everything passes -- even a blank line, or a "Version :"
751	+    // the program itself prints (no longer mistaken for the banner).
752	+    CHECK(f.classify(1, "") == Dest::kStdout);
753	+    CHECK(f.classify(1, "Version : my-app 2.0") == Dest::kStdout);
754	+  }
755	+
756	+  // --- no cycle line at all -> cycles() stays empty ---
757	+  {
758	+    VsimFilter f;
759	+    f.classify(2, "[info] hart 0 reset vector: 0x100000");
760	+    CHECK(!f.cycles().has_value());
761	+  }
762	+
763	+  // --- strip_vsim_banner: buffer-mode banner removal for the hybrid relay ---
764	+  // banner (+ trailing blank) then program output -> only the output survives
765	+  CHECK(strip_vsim_banner("Copyright (C) 2013-2026 Andes Technology "
766	+                          "Corporation.\nVersion : fcf5ecb\n\nhello\n") ==
767	+        "hello\n");
768	+  // banner only (ROI printed nothing) -> empty
769	+  CHECK(strip_vsim_banner("Copyright (C) ... Andes\nVersion : fcf5ecb\n\n") == "");
770	+  // no banner at all -> verbatim (the QEMU leg never has one; defensive)
771	+  CHECK(strip_vsim_banner("hello\nworld\n") == "hello\nworld\n");
772	+  // a final line without a trailing newline is preserved without one
773	+  CHECK(strip_vsim_banner("Version : x\n\nno newline") == "no newline");
774	+  // multi-line program output after the banner is kept whole
775	+  CHECK(strip_vsim_banner("Copyright (C) Andes\nVersion : x\n\nA\nB\n") ==
776	+        "A\nB\n");
